

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .function_call_status import FunctionCallStatus


class FunctionCall(UniversalBaseModel):
    """
    A function tool call that was generated by the model.
    """

    id: str = pydantic.Field()
    """
    The unique ID of the function call item.
    """

    call_id: str = pydantic.Field()
    """
    The unique ID of the function tool call that was generated.
    """

    name: str = pydantic.Field()
    """
    The name of the function that was called.
    """

    arguments: str = pydantic.Field()
    """
    The arguments JSON string that was generated.
    """

    status: FunctionCallStatus = pydantic.Field()
    """
    The status of the function call item that was recorded.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
